<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\DB;
class AdminMolecularSectionController extends Controller {public function edit(){$this->guard();return view('admin-molecular-section',['data'=>$this->data()]);}public function update(Request $request){$this->guard();$data=$request->validate(['heading'=>'required|string|max:180','description'=>'required|string|max:1500','card_heading'=>'required|array|size:4','card_heading.*'=>'required|string|max:100','card_description'=>'required|array|size:4','card_description.*'=>'required|string|max:500']);DB::table('section_settings')->updateOrInsert(['key'=>'molecular_specimens'],['value'=>json_encode($data),'updated_at'=>now(),'created_at'=>now()]);return back()->with('success','Molecular specimens section updated.');}private function data(){$row=DB::table('section_settings')->where('key','molecular_specimens')->value('value');return $row?json_decode($row,true):['heading'=>'Specimens Used for Molecular Testing','description'=>'Molecular testing can require different specimen types depending on the specific test and clinical indication. Final specimen requirements should always be based on Sterling’s current test menu and laboratory protocols.','card_heading'=>['Blood','Swab','Tissue','Other Specimens'],'card_description'=>['Used for selected molecular and genetic investigations.','May be used for selected infectious or respiratory testing.','May support specific oncology and molecular investigations.','Requirements vary according to the individual test.']];}private function guard(){abort_unless(Auth::check()&&Auth::user()->is_admin,403);}}
